Input: {"question": "What is Terry McDonald's profession?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0170-cb752ba522e2:d00", "start": 0, "end": 85, "text": "Mac McDonald Mac McDonald (born Terence McDonald; 18 June 1949) is an American actor."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0170-cb752ba522e2:d00", "start": 86, "end": 228, "text": "He is known for playing Captain Hollister on the BBC TV series \"Red Dwarf\" and frequently plays American characters in other British TV shows."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0170-cb752ba522e2:d00", "start": 229, "end": 358, "text": "He has also had many movie roles in films such as \"Aliens\", \"Batman\" and \"The Fifth Element\", all of which were filmed in London."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0170-cb752ba522e2:d00", "start": 359, "end": 402, "text": "McDonald was born in Long Island, New York."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0170-cb752ba522e2:d00", "start": 403, "end": 497, "text": "After leaving school, McDonald pursued a stage career, with a preference for comedy and music."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0170-cb752ba522e2:d00", "start": 498, "end": 579, "text": "In 1968 he was in Shreveport, Louisiana as the local TV station's Bozo the Clown."}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0170-cb752ba522e2:d01", "start": 0, "end": 155, "text": "Terry McDonald (footballer) Terry McDonald (born 12 November 1938) is an English former footballer who played mostly as a Winger, mainly for Leyton Orient."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0170-cb752ba522e2:d01", "start": 156, "end": 193, "text": "McDonald was born in Stepney, London."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0170-cb752ba522e2:d01", "start": 194, "end": 353, "text": "As a youngster, he was on the books of West Ham United, but only made one appearance in their first team, in a friendly against Spartak Prague in October 1958."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0170-cb752ba522e2:d01", "start": 354, "end": 512, "text": "As a member of West Ham's youth team, he played in the defeat to Manchester United, and had also played for England Youth against Hungary in Budapest in 1956."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0170-cb752ba522e2:d01", "start": 513, "end": 578, "text": "After West Ham had released McDonald following his demob from the"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0170-cb752ba522e2:d02", "start": 0, "end": 44, "text": "that appealed to children and adults alike ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0170-cb752ba522e2:d02", "start": 45, "end": 113, "text": "Open full sized image McDonald 's restaurant , Marrakech , Morocco ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0170-cb752ba522e2:d02", "start": 114, "end": 182, "text": "© Michael Hynes Over the years McDonald ’ s also expanded its menu ."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0170-cb752ba522e2:d02", "start": 183, "end": 294, "text": "In addition , restaurants in foreign countries also adapted their menus to appeal to local customs and tastes ."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0170-cb752ba522e2:d02", "start": 295, "end": 542, "text": "Filet-O-Fish sandwiches ( 1965 ) Quarter Pounders ( 1973 ) Egg McMuffins ( 1975 ) Full breakfast menu ( 1977 ) Happy Meals ( 1979 ) Chicken McNuggets ( 1983 ) In the late 20th century , McDonald ’ s moved beyond the hamburger business by acquiring"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0170-cb752ba522e2:d03", "start": 0, "end": 53, "text": "an artificial preservative , so skip it if you like ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0170-cb752ba522e2:d03", "start": 54, "end": 108, "text": "There are 580 calories in a Big Mac from McDonald 's ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0170-cb752ba522e2:d03", "start": 109, "end": 257, "text": "Pair it with any of our beverages or grab a Big Mac Combo Meal with our World Famous Fries® and Coca-Cola® or any of your favorite fountain drinks ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0170-cb752ba522e2:d03", "start": 258, "end": 490, "text": "Order a Big Mac today from the full menu in the app using Mobile Order & Pay for pickup or McDelivery ® * and earn points on eligible orders with MyMcDonald 's Rewards to redeem for a free Big Mac.^ * At participating McDonald ’ s ."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0170-cb752ba522e2:d03", "start": 491, "end": 501, "text": "McDelivery"}}, "original_cards": [{"doc_id": "ramdocs-0170-cb752ba522e2:d00", "card_id": "ramdocs-0170-cb752ba522e2:d00:c0", "entity": "Terry McDonald", "scope": "profession", "claim": "Terry McDonald is an actor.", "answer": "actor", "quote": "Mac McDonald Mac McDonald (born Terence McDonald; 18 June 1949) is an American actor.", "original_document_number": 1}, {"doc_id": "ramdocs-0170-cb752ba522e2:d01", "card_id": "ramdocs-0170-cb752ba522e2:d01:c0", "entity": "Terry McDonald", "scope": "profession", "claim": "Terry McDonald's profession is a footballer.", "answer": "footballer", "quote": "Terry McDonald (footballer) Terry McDonald (born 12 November 1938) is an English former footballer who played mostly as a Winger, mainly for Leyton Orient.", "original_document_number": 2}], "current_answers": ["actor", "footballer"], "candidate_answers": [{"candidate_id": "R0", "answer": "actor", "origin": "initial"}, {"candidate_id": "R1", "answer": "footballer", "origin": "initial"}]}
